"""Grid origin, cell layout, ordering and sheet-label maths.

Pure Python - see the package docstring for why. Everything here works on
plain tuples and numbers so it can be tested without QGIS.

Convention: row 0 is the *bottom* row, column 0 is the *left* column, matching
the way coordinates increase. Ordering functions are what turn that into the
order a plan set actually reads.
"""

import math

ANCHOR_CENTER = "center"
ANCHOR_LOWER_LEFT = "lower_left"
ANCHOR_SNAP = "snap"
ANCHOR_ORIGIN = "origin"

ORDER_ROW_NS = "row_ns"
ORDER_ROW_SN = "row_sn"
ORDER_COL = "col"
ORDER_SERPENTINE = "serpentine"


def count_along(span, cell, overlap):
    """How many cells of size ``cell`` overlapping by ``overlap`` cover ``span``.

    Returns ``(count, step)`` where ``step`` is the distance between the
    left edges of consecutive cells.
    """
    step = cell - overlap
    if cell <= 0:
        raise ValueError("Cell size must be positive")
    if step <= 0:
        raise ValueError(
            "Overlap (%s) must be smaller than the cell size (%s)" % (overlap, cell)
        )
    if span <= cell:
        return 1, step
    return int(math.ceil((span - cell) / step)) + 1, step


def grid_origin(bbox, cell_w, cell_h, overlap_x=0.0, overlap_y=0.0,
                anchor=ANCHOR_CENTER, snap_to=0.0, origin=None):
    """Work out where the grid starts and how many cells it needs.

    ``bbox`` is ``(xmin, ymin, xmax, ymax)``. Returns a dict with ``x0``,
    ``y0``, ``ncols``, ``nrows``, ``step_x`` and ``step_y``.
    """
    xmin, ymin, xmax, ymax = bbox
    if xmax < xmin or ymax < ymin:
        raise ValueError("Empty bounding box")

    if anchor == ANCHOR_ORIGIN:
        if origin is None:
            raise ValueError("anchor='origin' needs an origin")
        x0, y0 = float(origin[0]), float(origin[1])
    elif anchor == ANCHOR_SNAP:
        if snap_to <= 0:
            raise ValueError("anchor='snap' needs a positive snap interval")
        x0 = math.floor(xmin / snap_to) * snap_to
        y0 = math.floor(ymin / snap_to) * snap_to
    else:
        x0, y0 = xmin, ymin

    ncols, step_x = count_along(xmax - x0, cell_w, overlap_x)
    nrows, step_y = count_along(ymax - y0, cell_h, overlap_y)

    if anchor == ANCHOR_CENTER:
        # Re-centre the block of cells over the coverage so a site that is
        # 1.1 cells wide does not produce one full column and one near-empty
        # one hanging off the right-hand side.
        total_w = (ncols - 1) * step_x + cell_w
        total_h = (nrows - 1) * step_y + cell_h
        x0 = xmin - (total_w - (xmax - xmin)) / 2.0
        y0 = ymin - (total_h - (ymax - ymin)) / 2.0

    return {
        "x0": x0,
        "y0": y0,
        "ncols": ncols,
        "nrows": nrows,
        "step_x": step_x,
        "step_y": step_y,
    }


def cell_bounds(grid, cell_w, cell_h, row, col):
    """Bounds of one cell as ``(xmin, ymin, xmax, ymax)``."""
    xmin = grid["x0"] + col * grid["step_x"]
    ymin = grid["y0"] + row * grid["step_y"]
    return (xmin, ymin, xmin + cell_w, ymin + cell_h)


def order_cells(cells, mode=ORDER_ROW_NS):
    """Sort ``(row, col)`` pairs into sheet order.

    ``row_ns`` reads the top row left to right, then the next row down -
    the way a plan set is normally numbered. ``serpentine`` alternates
    direction each row, which minimises the pan between consecutive sheets
    when reviewing on screen.
    """
    cells = list(cells)
    if mode == ORDER_ROW_NS:
        return sorted(cells, key=lambda rc: (-rc[0], rc[1]))
    if mode == ORDER_ROW_SN:
        return sorted(cells, key=lambda rc: (rc[0], rc[1]))
    if mode == ORDER_COL:
        return sorted(cells, key=lambda rc: (rc[1], -rc[0]))
    if mode == ORDER_SERPENTINE:
        rows = sorted({rc[0] for rc in cells}, reverse=True)
        out = []
        for index, row in enumerate(rows):
            in_row = sorted((rc for rc in cells if rc[0] == row),
                            key=lambda rc: rc[1],
                            reverse=bool(index % 2))
            out.extend(in_row)
        return out
    raise ValueError("Unknown ordering mode %r" % mode)


def band_rows(items, band_ratio=0.5, axis="y"):
    """Group sheets into rows (or columns) by where they actually sit.

    ``items`` maps a key to ``(cx, cy, width, height)``. Returns a list of
    bands: rows ordered top to bottom (``axis="y"``) or columns ordered left to
    right (``axis="x"``), each band ordered left to right (or top to bottom).

    This is the part that survives a human moving sheets around. Row and column
    indices from the original grid stop meaning anything the moment a sheet is
    dragged; a sheet's position never stops meaning something. A new band
    starts when a sheet's centre is more than ``band_ratio`` of a sheet away
    from the one that opened the current band, so nudging a sheet sideways
    keeps it in its row and dropping it a full sheet down starts a new one.
    """
    if not items:
        return []
    if band_ratio <= 0:
        raise ValueError("band_ratio must be positive")

    if axis == "y":
        primary, size_index, reverse = 1, 3, True
        secondary, secondary_reverse = 0, False
    elif axis == "x":
        primary, size_index, reverse = 0, 2, False
        secondary, secondary_reverse = 1, True
    else:
        raise ValueError("axis must be 'x' or 'y'")

    ordered = sorted(items, key=lambda k: items[k][primary], reverse=reverse)

    bands = []
    current = []
    reference = None
    for key in ordered:
        position = items[key][primary]
        extent = abs(items[key][size_index]) or 0.0
        if current and abs(position - reference) > band_ratio * max(extent, 1e-9):
            bands.append(current)
            current = []
        if not current:
            reference = position
        current.append(key)
    if current:
        bands.append(current)

    return [
        sorted(band, key=lambda k: items[k][secondary], reverse=secondary_reverse)
        for band in bands
    ]


def order_by_position(items, mode=ORDER_ROW_NS, band_ratio=0.5):
    """Sheet order for features at arbitrary positions.

    Returns ``(ordered_keys, bands)``. The bands come back too because sheet
    ids, grid references and neighbours all need to know which row a sheet
    landed in.
    """
    if mode in (ORDER_ROW_NS, ORDER_ROW_SN, ORDER_SERPENTINE):
        bands = band_rows(items, band_ratio, axis="y")
        if mode == ORDER_ROW_SN:
            bands = list(reversed(bands))
        if mode == ORDER_SERPENTINE:
            ordered = []
            for index, band in enumerate(bands):
                ordered.extend(band if index % 2 == 0 else list(reversed(band)))
            return ordered, bands
        return [key for band in bands for key in band], bands
    if mode == ORDER_COL:
        bands = band_rows(items, band_ratio, axis="x")
        return [key for band in bands for key in band], bands
    raise ValueError("Unknown ordering mode %r" % mode)


def _overlap(a_centre, a_size, b_centre, b_size):
    low = max(a_centre - a_size / 2.0, b_centre - b_size / 2.0)
    high = min(a_centre + a_size / 2.0, b_centre + b_size / 2.0)
    return max(0.0, high - low)


def neighbours_by_position(items, band_ratio=0.5):
    """Which sheet is north, south, east and west of each one.

    Always worked out from rows, whatever order the sheets are numbered in -
    a match-line callout means the sheet next to this one on the ground, not
    the next number in the set.
    """
    rows = band_rows(items, band_ratio, axis="y")
    result = {}
    for row_index, row in enumerate(rows):
        for position, key in enumerate(row):
            cx, _, width, _ = items[key]
            entry = {
                "w": row[position - 1] if position > 0 else None,
                "e": row[position + 1] if position + 1 < len(row) else None,
                "n": None,
                "s": None,
            }
            for direction, other_index in (("n", row_index - 1), ("s", row_index + 1)):
                if not 0 <= other_index < len(rows):
                    continue
                best, best_overlap = None, 0.0
                for candidate in rows[other_index]:
                    ox, _, owidth, _ = items[candidate]
                    shared = _overlap(cx, width, ox, owidth)
                    if shared > best_overlap:
                        best, best_overlap = candidate, shared
                entry[direction] = best
            result[key] = entry
    return result


def alpha_label(index):
    """0 -> A, 25 -> Z, 26 -> AA. Spreadsheet-style column labels."""
    if index < 0:
        raise ValueError("Index must not be negative")
    label = ""
    index += 1
    while index > 0:
        index, remainder = divmod(index - 1, 26)
        label = chr(ord("A") + remainder) + label
    return label


def format_sheet_id(template, n, row, col, nrows=None, ncols=None):
    """Render a sheet id from a template such as ``C-{n:02d}`` or ``{alpha_row}{col1}``.

    Available fields: ``n``, ``row``, ``col`` (0-based, from the bottom left),
    ``row1``, ``col1`` (1-based), ``alpha_row``, ``alpha_col``.

    Rows are lettered from the top down, because that is how a key map reads.
    """
    row_from_top = (nrows - 1 - row) if nrows else row
    fields = {
        "n": n,
        "row": row,
        "col": col,
        "row1": row + 1,
        "col1": col + 1,
        "alpha_row": alpha_label(row_from_top),
        "alpha_col": alpha_label(col),
    }
    try:
        return template.format(**fields)
    except (KeyError, IndexError) as exc:
        raise ValueError(
            "Unknown field %s in template %r. Available: %s"
            % (exc, template, ", ".join(sorted(fields)))
        )
    except ValueError as exc:
        raise ValueError("Bad template %r: %s" % (template, exc))


def rotate_point(x, y, cx, cy, degrees_clockwise):
    """Rotate a point clockwise about a centre, matching QgsGeometry.rotate()."""
    theta = math.radians(-degrees_clockwise)
    dx, dy = x - cx, y - cy
    cos_t, sin_t = math.cos(theta), math.sin(theta)
    return (cx + dx * cos_t - dy * sin_t, cy + dx * sin_t + dy * cos_t)
